fn bounded_files<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<Vec<PayloadFile>, D::Error> {
    struct Visitor;
    impl<'de> serde::de::Visitor<'de> for Visitor {
        type Value = Vec<PayloadFile>;
        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result { f.write_str("a bounded file list") }
        fn visit_seq<A: serde::de::SeqAccess<'de>>(self, mut seq: A) -> Result<Self::Value, A::Error> {
            if seq.size_hint().is_some_and(|n| n > MAX_FILES) {
                return Err(serde::de::Error::custom("too many backup files"));
            }
            let mut files = Vec::new();
            while let Some(file) = seq.next_element()? {
                if files.len() == MAX_FILES { return Err(serde::de::Error::custom("too many backup files")); }
                files.push(file);
            }
            Ok(files)
        }
    }
    deserializer.deserialize_seq(Visitor)
}

fn validate_files(payload: &Payload) -> Result<()> {
    if payload.files.len() > MAX_FILES { bail!("too many backup files"); }
    let mut paths = std::collections::BTreeSet::new();
    for file in &payload.files {
        if !super::layout::is_safe_branch_path(&file.path)
            || !matches!(file.mode.as_str(), "100644" | "100755" | "120000" | "160000")
            || !paths.insert(file.path.as_str()) {
            bail!("invalid or duplicate backup file path/mode");
        }
        if file.mode == "160000" && !(file.content.0.len() == 40 && file.content.0.iter().all(u8::is_ascii_hexdigit)) {
            bail!("invalid gitlink object id");
        }
    }
    for path in &paths {
        for (index, _) in path.match_indices('/') {
            if paths.contains(&path[..index]) { bail!("overlapping backup file paths"); }
        }
    }
    Ok(())
}

pub(crate) fn validate_identity(repo: &HistoryRepo, commit: &str, machine: &str, uuid: &str, checkpoint: &Checkpoint) -> Result<()> {
    let header = header_of(repo, commit)?.ok_or_else(|| eyre::eyre!("missing encrypted backup header"))?;
    if header.machine.id != machine || header.checkpoint != uuid || header.machine != checkpoint.machine
        || header.checkpoint != checkpoint.uuid || header.created_at != checkpoint.created_at {
        bail!("encrypted backup identity does not match its header and ref");
    }
    Ok(())
}

pub(crate) async fn materialize_checked(repo: &HistoryRepo, commit: &str, machine: &str, uuid: &str) -> Result<String, ReadError> {
    let payload = read_payload(repo, commit).await?;
    validate_identity(repo, commit, machine, uuid, &payload.checkpoint)?;
    Ok(materialize_payload(repo, &payload)?)
}

